function renderHome(){
 const custom=state.plans.filter(p=>!p.prepared&&!p.course&&!p.sourceExact);
 $('#content').innerHTML=heading('O teu treino.<br>A tua evolução.','Planos e registos organizados no mesmo lugar. Cada conta tem os seus próprios dados.')+`<section class="program-intro"><span class="eyebrow">Começa aqui</span><h2 style="margin:10px 0">Escolhe o teu ponto de partida</h2><p>Cria uma ficha, importa um plano ou usa o modelo de 12 semanas com rotinas públicas do Bioforceman. O modelo deve ser ajustado ao teu nível e material.</p><div class="home-actions"><button class="btn" id="home-new">+ Criar plano</button><button class="btn secondary" id="home-template">${state.courseEnabled?'Continuar o programa de 12 semanas':'Usar modelo de 12 semanas'}</button><button class="btn secondary" id="home-import">Importar plano / cópia</button></div></section>${custom.length?`<section class="program-intro"><h2>Os meus planos</h2><div class="other-plans">${custom.map(p=>`<button class="other-plan" data-home-plan="${esc(p.id)}"><strong>${esc(p.name)}</strong><span>${p.exercises.length} exercícios →</span></button>`).join('')}</div></section>`:''}<section class="program-intro"><h3>Gravação e cópias de segurança</h3><p>Entra na tua conta para sincronizar os planos, rascunhos e histórico. Sem ligação, os dados ficam neste navegador e são enviados quando a ligação regressar. O estado de gravação aparece no topo.</p><p>Se vens da página anterior, exporta lá a tua cópia JSON e importa-a aqui depois de entrares. Para outra pessoa, usa outra conta: os dados não se misturam.</p></section>`;
 $('#home-new').onclick=newPlanForm;$('#home-import').onclick=()=>$('#import-file').click();$('#home-template').onclick=()=>{const w=state.courseEnabled?state.courseWeek||1:1;state.courseEnabled=true;persist();chooseCourse(w,state.courseSession||'A')};document.querySelectorAll('[data-home-plan]').forEach(b=>b.onclick=()=>{selectedPlan=b.dataset.homePlan;renderPlans()});
}
function loadAccountState(next,key){
 state=next;activeStorageKey=key;storageOK=true;$('#storage-error').hidden=true;installPrepared();state.courseEnabled??=true;selectedPlan=state.courseEnabled===false?'':courseId(state.courseWeek||1,state.courseSession||'A');view='plans';render();
}
const KEY='bioforceman-treino-v1';
let activeStorageKey=KEY;
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({library:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',plans:'<path d="M8 5H5a2 2 0 0 0-2 2v13a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1V7a2 2 0 0 0-2-2h-3"/><rect x="8" y="2" width="8" height="6" rx="2"/><path d="m7 14 3 3 7-7"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>'})[name]||''}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unitLabel=e=>({s:'s',steps:'passos',reps:'reps'}[e.unit]||'reps');
const targetLabel=e=>{const t=String(e.target||'Objetivo pessoal'),m=t.match(/^(.*?)( por (?:lado|direção))$/);return m?m[1]+' '+unitLabel(e)+m[2]:t+' '+unitLabel(e)};
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const blankRow=()=>({kg:'',reps:'',done:false});
const ex=(name,video,sets=1,start=0,note='')=>({id:uid(),name,video,sets,target:'',unit:'reps',start,note});
const fresh=()=>({version:1,programRevision:13,courseVersion:2,courseEnabled:false,courseWeek:1,courseSession:'A',courseChecks:{},favorites:[],plans:JSON.parse(JSON.stringify(PREPARED)),drafts:{},history:[]});
let state,storageOK=true,view='plans',category='Todos',format='Todos',search='',page=1,favOnly=false,selectedPlan='',toastTimeout,restDuration=90,restRemaining=90,restUntil=0,restRunning=false;
const $=s=>document.querySelector(s);
function warnStorage(msg){storageOK=false;$('#storage-error').hidden=false;$('#storage-error').textContent=msg;}
function validState(d){
 const safeKeys=x=>!x||typeof x!=='object'||Object.entries(x).every(([k,v])=>!['__proto__','constructor','prototype'].includes(k)&&safeKeys(v));
 if(!safeKeys(d))return false;
 if(!d||d.version!==1||!Array.isArray(d.plans)||!d.plans.length||d.plans.length>256||!Array.isArray(d.history)||d.history.length>10000||!Array.isArray(d.favorites)||d.favorites.length>1000||!d.drafts||typeof d.drafts!=='object'||Array.isArray(d.drafts))return false;
 const text=(v,n=2000)=>typeof v==='string'&&v.length<=n;
 const safeId=v=>text(v,100)&&/^[A-Za-z0-9_-]+$/.test(v)&&!['__proto__','constructor','prototype'].includes(v);
 const num=(v,max=100000)=>v===''||(typeof v==='string'&&v.length<20&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=max);
 const video=v=>text(v,11)&&(!v||/^[\w-]{11}$/.test(v));
 const row=r=>r&&num(r.kg)&&num(r.reps)&&typeof r.done==='boolean';
 const courseMeta=c=>c&&typeof c==='object'&&!Array.isArray(c)&&Number.isInteger(c.week)&&c.week>=1&&c.week<=12&&['A','B','C','M'].includes(c.session)&&Number.isInteger(c.phase)&&c.phase>=0&&c.phase<=3;
 const exercise=e=>e&&safeId(e.id)&&text(e.name,200)&&e.name.trim()&&video(e.video)&&Number.isInteger(e.sets)&&e.sets>=1&&e.sets<=30&&text(e.target,60)&&['reps','s','steps'].includes(e.unit)&&Number.isInteger(e.start)&&e.start>=0&&e.start<=86400&&text(e.note);
 if(d.courseWeek!==undefined&&(!Number.isInteger(d.courseWeek)||d.courseWeek<1||d.courseWeek>12))return false;
 if(d.courseSession!==undefined&&!['A','B','C','M'].includes(d.courseSession))return false;
 if(!d.favorites.every(v=>/^[\w-]{11}$/.test(v)))return false;
 if(!d.plans.every(p=>p&&safeId(p.id)&&text(p.name,100)&&p.name.trim()&&text(p.note)&&Array.isArray(p.exercises)&&p.exercises.length<=100&&p.exercises.every(exercise)&&(!p.course||courseMeta(p.course))))return false;
 if(new Set(d.plans.map(p=>p.id)).size!==d.plans.length||d.plans.some(p=>new Set(p.exercises.map(e=>e.id)).size!==p.exercises.length))return false;
 const date=v=>text(v,10)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00'));
 const record=e=>e&&safeId(e.id)&&text(e.name,200)&&['reps','s','steps'].includes(e.unit)&&Array.isArray(e.rows)&&e.rows.length<=30&&e.rows.every(row);
 for(const draft of Object.values(d.drafts)){
  if(draft?.editHistoryId!==undefined&&!safeId(draft.editHistoryId))return false;
  if(!draft||!date(draft.date)||!text(draft.note)||!draft.rows||typeof draft.rows!=='object'||Array.isArray(draft.rows)||Object.keys(draft.rows).length>100)return false;
  if(!Object.values(draft.rows).every(a=>Array.isArray(a)&&a.length<=30&&a.every(row)))return false;
 }
 if(!d.history.every(h=>h&&safeId(h.id)&&text(h.planName,100)&&date(h.date)&&text(h.note)&&Number.isFinite(h.savedAt)&&Array.isArray(h.exercises)&&h.exercises.length<=100&&h.exercises.every(record)&&(!h.course||courseMeta(h.course))&&(h.complete===undefined||typeof h.complete==='boolean')&&(h.duration===undefined||num(h.duration,240))))return false;
 return true;
}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validState(parsed))throw Error('invalid');state=parsed;}else state=fresh();}catch(e){state=fresh();warnStorage('Não foi possível ler os registos deste navegador. Os dados existentes não serão substituídos. Exporta uma cópia dos novos registos antes de fechar.');}
function persist(){if(!storageOK)return false;try{localStorage.setItem(activeStorageKey,JSON.stringify(state));if(window.TreinoCloud)window.TreinoCloud.changed();return true;}catch(e){warnStorage('Não foi possível guardar no navegador. Mantém a página aberta e exporta uma cópia de segurança para não perderes os registos.');return false;}}
function toast(msg){$('#toast').textContent=msg;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').textContent='',4000)}
function getPlan(){return state.plans.find(p=>p.id===selectedPlan)||state.plans[0]}
function getDraft(p){if(!Object.hasOwn(state.drafts,p.id))state.drafts[p.id]={date:today(),note:'',rows:{}};const d=state.drafts[p.id];if(d.date!==today()&&!d.datePinned&&!d.note&&Object.values(d.rows).every(rs=>rs.every(r=>!r.kg&&!r.reps&&!r.done)))d.date=today();p.exercises.forEach(e=>{if(!Object.hasOwn(d.rows,e.id))d.rows[e.id]=Array.from({length:e.sets},blankRow)});return d;}
function setView(v){view=v;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});if(view==='library')renderLibrary();if(view==='plans'){if(!selectedPlan)renderHome();else renderPlans();}if(view==='history')renderHistory();}
function duration(v){return v.duration?`${Math.floor(v.duration/60)}:${String(v.duration%60).padStart(2,'0')}`:v.type}
function heading(title,subtitle,extra=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="subtext">${subtitle}</p></div>${extra}</div>`}
function renderLibrary(){
 $('#content').innerHTML=heading('A tua biblioteca<br>de treino.','Explora, escolhe e passa à prática. Os vídeos do canal, com espaço para a tua evolução.',`<span class="count-chip">${CATALOG.length} vídeos · 1 lugar</span>`)+`<section class="hero" aria-label="Rotina em destaque"><div class="hero-content"><span class="eyebrow">Começa por aqui · rotina pública</span><h2>Três movimentos.<br>Uma base de força.</h2><p>Flexão, split squat e remada.<br>Vê a progressão e regista o teu treino.</p><button class="btn lime" id="open-feature">Abrir treino de força <span aria-hidden="true">↗</span></button></div><button class="hero-image" id="video-feature" aria-label="Ver vídeo Build Full Body Strength in 14 Days"><img src="https://i.ytimg.com/vi/0QXSICOie5c/hqdefault.jpg" alt="" referrerpolicy="no-referrer"><span class="play" aria-hidden="true">▶</span></button></section><div class="section-title"><h2>Explorar os vídeos</h2><span class="results-count" id="result-count"></span></div><div class="toolbar"><div class="search">${icon('search')}<input id="search" type="search" placeholder="Pesquisar: ombros, push-ups, rotina…" aria-label="Pesquisar vídeos" value="${esc(search)}"></div><select id="format" aria-label="Formato"><option value="Todos">Todos os formatos</option><option>Vídeo</option><option>Short</option></select><button class="btn secondary" id="favorites" aria-pressed="${favOnly}">${favOnly?'★':'☆'} Favoritos</button></div><div class="chips" role="group" aria-label="Filtrar por tema">${['Todos','Rotinas','Peito','Costas','Ombros','Braços','Pernas','Core','Mobilidade','Geral'].map(c=>`<button class="chip ${category===c?'active':''}" data-cat="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><div id="video-grid" class="grid"></div><div id="pages" class="pagination"></div><p class="privacy">Os temas são organizados a partir dos títulos. O catálogo inclui rotinas, exercícios e vídeos explicativos. Podes adicionar novos vídeos manualmente aos teus treinos.</p>`;
 $('#format').value=format;$('#search').oninput=e=>{search=e.target.value;page=1;renderCards()};$('#format').onchange=e=>{format=e.target.value;page=1;renderCards()};$('#favorites').onclick=()=>{favOnly=!favOnly;page=1;renderLibrary()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;page=1;renderLibrary()});$('#video-feature').onclick=()=>openVideo('0QXSICOie5c');$('#open-feature').onclick=()=>{selectedPlan=state.plans.find(p=>p.exercises.some(e=>e.video==='0QXSICOie5c'))?.id||state.plans[0].id;setView('plans')};renderCards();
}
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function renderCards(){
 const synonyms={'ombros':'shoulder delt','bracos':'arm bicep tricep forearm','peito':'chest push','costas':'back pull row','pernas':'leg squat calv','rotina':'routine','flexao':'push-up pushup','abdominais':'abs core','corpo inteiro':'full body','principiante':'beginner'};
 const query=normalize(search.trim());const words=(synonyms[query]||'').split(' ').filter(Boolean);
 const filtered=CATALOG.filter(v=>(category==='Todos'||v.tags.includes(category))&&(format==='Todos'||v.type===format)&&(!favOnly||state.favorites.includes(v.id))&&(!query||normalize(v.title+' '+v.tags.join(' ')).includes(query)||words.some(w=>normalize(v.title).includes(w))));
 const total=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,total);$('#result-count').textContent=`${filtered.length} resultados`;
 $('#video-grid').innerHTML=filtered.length?filtered.slice((page-1)*12,page*12).map(v=>`<article class="video-card"><div class="cover"><button class="cover-open" data-video="${v.id}" aria-label="Ver ${esc(v.title)}"><img loading="lazy" src="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg" alt="" referrerpolicy="no-referrer"></button><span class="duration">${duration(v)}</span><button class="fav ${state.favorites.includes(v.id)?'saved':''}" data-fav="${v.id}" aria-label="${state.favorites.includes(v.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(v.title)}" aria-pressed="${state.favorites.includes(v.id)}">${state.favorites.includes(v.id)?'★':'☆'}</button></div><h3><button class="title-button" data-video="${v.id}">${esc(v.title)}</button></h3><div class="meta"><span class="type">${v.type}</span><span>${v.tags.slice(0,2).join(' · ')}</span></div></article>`).join(''):'<div class="empty" style="grid-column:1/-1"><h3>Nenhum vídeo encontrado</h3>Experimenta outro tema ou termo de pesquisa.</div>';
 $('#pages').innerHTML=filtered.length?`<button class="btn secondary" id="prev" ${page===1?'disabled':''}>← Anterior</button><span>${page} / ${total}</span><button class="btn secondary" id="next" ${page===total?'disabled':''}>Seguinte →</button>`:'';
 document.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>openVideo(b.dataset.video));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{const id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();renderCards()});
 if($('#prev'))$('#prev').onclick=()=>{page--;renderCards();$('#search').scrollIntoView({block:'start'})};if($('#next'))$('#next').onclick=()=>{page++;renderCards();$('#search').scrollIntoView({block:'start'})};
}
function modal(title,body,small=false){$('#modal').classList.toggle('small-dialog',small);$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=body;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close();$('#dialog-content').innerHTML=''}
$('#modal .close').onclick=closeModal;$('#modal').addEventListener('cancel',()=>{$('#dialog-content').innerHTML=''});
// Remove the embedded player before the external YouTube tab opens.
$('#dialog-content').addEventListener('click',event=>{if(event.target.closest('.video-links a[target="_blank"]'))closeModal();});
function openVideo(id,start=0){const v=CATALOG.find(v=>v.id===id);const exercise=state.plans.flatMap(p=>p.exercises).find(e=>e.video===id);const title=v?.title||exercise?.name||'Demonstração do exercício';const matching=state.plans.find(p=>p.video===id&&p.sourceExact);modal('Ver e praticar',`<div class="video-modal-grid"><div><div class="player"><iframe src="https://www.youtube-nocookie.com/embed/${esc(id)}?start=${Math.max(0,start)}&rel=0" title="${esc(title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="video-links"><a href="https://www.youtube.com/watch?v=${esc(id)}&t=${start}s" target="_blank" rel="noopener">Abrir no YouTube ↗</a><span>${v?'Bioforceman':'Vídeo de demonstração'}</span></div><p class="dialog-note">Se o leitor não funcionar ao abrir o ficheiro HTML, usa “Abrir no YouTube”. Os vídeos precisam de internet.</p></div><div class="video-description"><span class="eyebrow">${esc(v?.type||'Vídeo de referência')}</span><h3 style="margin-top:8px">${esc(title)}</h3><p>Consulta a demonstração e regressa à ficha para seguir as séries, os objetivos e as notas.</p>${matching?`<button class="btn full" id="follow-prepared">Seguir este treino completo →</button><p class="dialog-note">${matching.exercises.length} exercícios já preparados, com as doses do excerto.</p>`:''}<label for="add-plan">Adicionar a</label><select id="add-plan">${state.plans.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><button id="video-add" class="btn full">${icon('plus')} Adicionar exercício</button><p class="dialog-note">Um vídeo pode mostrar vários exercícios. Adiciona uma linha de registo por movimento.</p></div></div>`);if($('#follow-prepared'))$('#follow-prepared').onclick=()=>{selectedPlan=matching.id;closeModal();setView('plans')};$('#video-add').onclick=()=>{selectedPlan=$('#add-plan').value;closeModal();view='plans';render();exerciseForm(null,id)};}
function sourceComparison(p){return `<div class="source-comparison"><div class="source-comparison-title"><h3>Os seis exercícios · pela ordem do vídeo</h3><a href="https://www.youtube.com/watch?v=${esc(p.video)}" target="_blank" rel="noopener">Ver a rotina original ↗</a></div><p class="comparison-note">A lista original mantém-se visível. A coluna desta semana é a dose a seguir e registar, ajustada aos teus 30–45 minutos.</p><ol>${p.exercises.map(e=>`<li><div class="comparison-name"><strong>${esc(e.originalName||e.name)}</strong>${e.adaptation?`<small>Adaptação: ${esc(e.adaptation)}</small>`:''}${e.adapted?`<small>Alternativa selecionada: ${esc(e.name)}</small>`:''}</div><div class="comparison-dose"><span><b>No vídeo</b>${esc(e.originalDose||'—')}</span><span><b>Semana ${p.course.week}</b>${e.sets} × ${esc(targetLabel(e))}</span></div></li>`).join('')}</ol><p class="comparison-note">Uma série unilateral inclui os dois lados. Começa leve nos movimentos novos; as semanas 4 e 8 reduzem volume. A e B mantêm estas rotinas para poderes progredir; C muda de rotina no bloco 2.</p></div>`}
function courseWeek(p=getPlan()){return p.course?.session==='M'?state.courseWeek||1:p.course?.week||state.courseWeek||1}
function isCurrentCourse(p){return p.course?.version===COURSE.version&&p.id.startsWith(COURSE.prefix+'-')}
function courseId(week,session='A'){return session==='M'?COURSE.prefix+'-mobility':`${COURSE.prefix}-w${String(week).padStart(2,'0')}-${session}`}
function chooseCourse(week,session='A'){state.courseWeek=week;state.courseSession=session;selectedPlan=courseId(week,session);persist();renderPlans()}
function courseDone(id){return state.history.some(h=>h.planId===id&&h.complete===true)}
function courseBoard(p){const week=courseWeek(p),meta=COURSE.weeks[week-1],completed=state.plans.filter(x=>isCurrentCourse(x)&&x.course.session!=='M'&&courseDone(x.id)).length;const check=state.courseChecks?.[week]||{};
 return `<details class="course-calendar"><summary>Semana ${week} · ${esc(meta.focus)} <span>${completed}/36 completas · escolher semana e ver progressão ⌄</span></summary><section class="course-board"><div class="course-topline"><span class="eyebrow">Programa próprio · inspirado no Bioforceman</span><span>${completed} / 36 sessões completas</span></div><div class="course-blocks">${[1,2,3].map(n=>`<span class="${meta.phase===n?'current':''}"><b>0${n}</b>${n===1?'Base e controlo':n===2?'Construção':'Força e consolidação'}<small>Semanas ${n===1?'1–4':n===2?'5–8':'9–12'}</small></span>`).join('')}</div><div class="course-weeks" role="group" aria-label="Escolher semana">${COURSE.weeks.map(w=>`<button data-course-week="${w.week}" class="${week===w.week?'current':''} ${w.light?'light-week':''}" aria-pressed="${week===w.week}"><span>Sem.</span><b>${w.week}</b><small>${['A','B','C'].filter(s=>courseDone(courseId(w.week,s))).length}/3</small></button>`).join('')}</div><div class="course-week-focus"><div><b>Semana ${week} · ${esc(meta.focus)}</b><p>${meta.light?'Volume reduzido para consolidar; repete o bloco anterior se ainda não recuperaste bem.':meta.review?'Compara com a semana 2, usando a mesma variante e unidade, sem testar máximos.':'Margem planeada: cerca de '+esc(meta.rir)+' boas repetições ainda possíveis no fim da série.'}</p></div><button class="btn secondary" id="course-overview">Ver as 12 semanas ↗</button></div><div class="course-actions"><button class="mini" id="course-sources">Exercícios, fontes e adaptações</button><button class="mini" id="course-profile">Como usar este modelo</button><button class="mini" id="course-originals">Rotinas originais dos vídeos</button></div><details class="course-check"><summary>Revisão da semana · peso, cintura e recuperação</summary><div class="check-fields"><label>Peso corporal · kg<input type="number" min="20" max="300" step="0.1" data-course-check="weight" value="${esc(check.weight||'')}" placeholder="Opcional"></label><label>Cintura · cm<input type="number" min="30" max="200" step="0.5" data-course-check="waist" value="${esc(check.waist||'')}" placeholder="Opcional"></label><label>Notas da semana<input maxlength="1000" data-course-check="note" value="${esc(check.note||'')}" placeholder="Recuperação, esforço, variantes…"></label></div><p>Usa um método consistente e olha para tendências. Não há uma meta de perda de gordura localizada.</p></details></section></details>`;
}
function courseTabs(p){const w=courseWeek(p);return ['A','B','C','M'].map(s=>`<button class="plan-tab ${p.course.session===s?'active':''}" data-course-session="${s}">${s==='M'?'Intervalo · mobilidade':s+' · '+esc(state.plans.find(x=>x.id===courseId(w,s))?.shortTitle||s)}</button>`).join('')}
function bindCourse(p){const w=courseWeek(p);document.querySelectorAll('[data-course-week]').forEach(b=>b.onclick=()=>chooseCourse(+b.dataset.courseWeek,p.course.session));document.querySelectorAll('[data-course-session]').forEach(b=>b.onclick=()=>chooseCourse(w,b.dataset.courseSession));$('#course-overview').onclick=courseOverview;$('#course-sources').onclick=courseSources;$('#course-profile').onclick=courseProfile;$('#course-originals').onclick=courseOriginals;document.querySelectorAll('[data-course-check]').forEach(input=>input.oninput=()=>{if(input.type==='number'&&!input.checkValidity())return;state.courseChecks??={};state.courseChecks[w]??={};state.courseChecks[w][input.dataset.courseCheck]=input.value;persist()});}
function courseOverview(){modal('O programa de 12 semanas',`<p class="dialog-note" style="margin-top:0">Três sessões ao final do dia, com pelo menos um dia de intervalo. Mantém A → B → C; se falhares uma sessão, retoma a sequência. A semana seguinte não obriga a aumentar carga nem dificuldade.</p><div class="course-table"><table><thead><tr><th>Semana</th><th>Foco</th><th>Séries A / B / C</th><th>Margem</th></tr></thead><tbody>${COURSE.weeks.map(w=>`<tr><td>${w.week}</td><td>${esc(w.focus)}</td><td>${['A','B','C'].map(s=>state.plans.find(p=>p.id===courseId(w.week,s))?.exercises.reduce((n,e)=>n+e.sets,0)||'—').join(' / ')}</td><td>${esc(w.rir)} reps</td></tr>`).join('')}</tbody></table></div><div class="overview-rule"><b>Como aumentar a carga</b><p>Primeiro ganha repetições dentro da faixa. Quando completares as séries no topo da faixa, com a mesma amplitude, a margem planeada e boa recuperação, usa o menor aumento disponível. Volta à parte baixa da faixa. Se isso não acontecer, mantém a dose.</p></div><div class="overview-rule"><b>Como caber nos 30–45 minutos</b><p>Conta 5–6 min de aquecimento. Faz os exercícios pela ordem e usa os descansos da ficha. Nos unilaterais, uma série inclui os dois lados. Se o tempo acabar, guarda uma sessão parcial; não cortes a técnica ou o descanso para completar todos os cartões.</p></div><div class="overview-rule"><b>Se a resposta ao treino piorar</b><p>Não avances a variante só pelo calendário. Mantém a anterior, reduz a dose ou usa a alternativa. Se o desconforto persistir ou surgirem sintomas novos, revê com um profissional.</p></div><p class="dialog-note">As semanas 4 e 8 têm volume reduzido e a 12 serve para comparação submáxima. São escolhas deste programa, não fases copiadas do programa pago.</p>`);}
function courseProfile(){modal('Como usar este modelo',`<p>Este é um modelo de 12 semanas organizado a partir de rotinas públicas. Ativa-o apenas se corresponder ao teu nível, material e disponibilidade. Podes criar um plano próprio, editar os exercícios ou importar uma ficha recebida.</p><p>Guarda a carga por haltere ou o total da barra conforme a indicação de cada exercício. Não transfiras cargas automaticamente entre variantes.</p>`);}
function courseSources(){modal('Rotinas usadas no programa',`<p>A — Old Man Strength, com os seis movimentos que enviaste. B — Dense Muscle, com os seus seis movimentos. C — Progressive Overload nas semanas 1–4 e 9–12; Athletic Frame nas semanas 5–8.</p><p>As doses originais aparecem na tabela de cada sessão, ao lado da dose semanal. Os movimentos A estão preservados. Em B, a Renegade Row tem apoio elevado, identificado na ficha, para usar halteres desmontáveis sem apoiar o corpo sobre eles. Em C, as adaptações de banco estão identificadas quando não há banco inclinável. As outras variantes são escolhas opcionais.</p><div class="source-links">${[['Older Men','ACyCx_s15ME'],['Dense Muscle','hWa_i8RR9Rg'],['Progressive Overload','mR7QSD-p2vA'],['Athletic Frame','0597fJVl2sw']].map(([n,id])=>`<a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</div><p>Foram consultadas as descrições públicas de 67 vídeos longos, com cinco rotinas transcritas em fichas, e cinco transcrições complementares. Não vi todos os vídeos integralmente nem tive acesso ao programa pago. A sequência, o volume e a progressão destas 12 semanas são uma organização própria.</p>`);}
function courseOriginals(){const originals=state.plans.filter(p=>p.sourceExact);modal('Rotinas originais de referência',`<p class="dialog-note" style="margin-top:0">Estas fichas preservam as doses publicadas. Não são sessões para acrescentar ao programa pessoal; servem para veres a origem da seleção.</p><div class="other-plans">${originals.map(p=>`<button class="other-plan" data-original-plan="${esc(p.id)}"><strong>${esc(p.name)}</strong><span>${p.exercises.length} exercícios · ${p.exercises.reduce((n,e)=>n+e.sets,0)} séries ↗</span></button>`).join('')}</div>`,true);document.querySelectorAll('[data-original-plan]').forEach(b=>b.onclick=()=>{selectedPlan=b.dataset.originalPlan;closeModal();renderPlans()});}

function programSteps(p){
 if(p.id==='bf-morning-circuit'){return [0,1].flatMap(round=>p.exercises.map((e,i)=>({index:i,row:round,label:'Volta '+(round+1)+' de 2'})));}
 if(p.id==='bf-morning-complete'&&p.exercises.length===6){return [{index:0,row:null},{index:1,row:null},{index:2,row:null},{index:3,row:null},...[0,1,2].flatMap(r=>[{index:4,row:r,label:'Par '+(r+1)+' de 3'},{index:5,row:r,label:'Par '+(r+1)+' de 3'}])];}
 return p.exercises.map((e,i)=>({index:i,row:null}));
}
function installPrepared(){
 if(state.programRevision===13&&state.courseVersion===2)return;
 const upgrading=state.courseVersion!==2;
 const wanted=JSON.parse(JSON.stringify(PREPARED)).filter(p=>!state.plans.some(x=>x.id===p.id));
 state.plans=[...wanted.slice(0,Math.max(0,256-state.plans.length)),...state.plans];
 if(upgrading){state.courseVersion=2;state.courseWeek=1;state.courseSession='A';state.previousCourseChecks=state.courseChecks||{};state.courseChecks={};}
 if(!Number.isInteger(state.courseWeek)||state.courseWeek<1||state.courseWeek>12)state.courseWeek=1;
 if(!['A','B','C','M'].includes(state.courseSession))state.courseSession='A';
 if(!state.courseChecks||typeof state.courseChecks!=='object'||Array.isArray(state.courseChecks))state.courseChecks={};
 state.programRevision=13;
}
function previousExercise(e,date){
 const sessions=state.history.filter(h=>h.date<date).sort((a,b)=>b.date.localeCompare(a.date)||b.savedAt-a.savedAt);
 for(const h of sessions){const match=h.exercises.find(x=>x.id===e.id&&x.unit===e.unit&&x.name===e.name);if(match&&match.rows.length)return {date:h.date,rows:match.rows};}return null;
}
function otherPlans(){const ps=state.plans.filter(p=>!isCurrentCourse(p));modal('Arquivo de planos e rotinas de referência',`<p class="dialog-note" style="margin-top:0">O programa pessoal tem o seu seletor de semanas e sessões. Estas fichas anteriores e rotinas de referência mantêm-se acessíveis; não são trabalho para somar ao programa.</p><div class="other-plans">${ps.map(p=>`<button class="other-plan" data-other-plan="${esc(p.id)}"><strong>${p.course?'Programa anterior · ':''}${esc(p.name)}</strong><span>${p.exercises.length} exercícios${p.duration?' · '+esc(p.duration):''} ↗</span></button>`).join('')}</div>`,true);document.querySelectorAll('[data-other-plan]').forEach(b=>b.onclick=()=>{selectedPlan=b.dataset.otherPlan;closeModal();renderPlans()});}
function changeVariant(e){const d=getDraft(getPlan());if((d.rows[e.id]||[]).some(r=>r.kg||r.reps||r.done))return toast('Guarda a sessão antes de trocar a variante deste exercício.');const alternative=e.alternative;if(!alternative)return;const before={};for(const k of ['name','video','start','how','cue','note','sourceDose','unit','target','loadHint','restSeconds'])before[k]=e[k]||'';before.label=e.adapted?'Usar alternativa preparada':'Voltar ao movimento da ficha';for(const k of ['name','video','start','how','cue','note','sourceDose','unit','target','loadHint','restSeconds'])if(alternative[k]!==undefined)e[k]=alternative[k];e.loadHint=alternative.loadHint||'Variante alterada: recalibra a carga e confirma a unidade indicada na ficha.';e.alternative=before;e.adapted=!e.adapted;persist();renderPlans();toast('Variante atualizada. O histórico anterior mantém-se.');}
function renderPlans(){const p=getPlan();selectedPlan=p.id;const d=getDraft(p);if(typeof d.guided!=='boolean')d.guided=true;const steps=programSteps(p);d.step=Math.max(0,Math.min(Number.isInteger(d.step)?d.step:0,Math.max(0,steps.length-1)));const current=steps[d.step];const total=p.exercises.reduce((n,e)=>n+(d.rows[e.id]||[]).length,0);const primaries=state.plans.filter(p=>p.primary);const previous=state.history.filter(h=>h.planName===p.name).sort((a,b)=>b.date.localeCompare(a.date))[0];
 $('#content').innerHTML=heading(isCurrentCourse(p)?'Os treinos dos vídeos.<br>O teu plano de 12 semanas.':p.sourceExact?'Rotina original do vídeo.':'Plano guardado.',isCurrentCourse(p)?'Três sessões complementares ao final do dia, em 30–45 min. Mobilidade nos intervalos e progressão sem pressa.':p.sourceExact?'Ficha de referência da descrição pública. O programa pessoal está separado.':'Edita a ficha e regista cada sessão. Os registos guardados mantêm-se no histórico.')+(isCurrentCourse(p)?courseBoard(p):'')+`<div class="plan-tabs">${isCurrentCourse(p)?courseTabs(p):'<button class="plan-tab" id="course-home">← Os meus treinos</button>'}<button class="plan-tab" id="other-plans">Arquivo de planos</button>${isCurrentCourse(p)?'':'<button class="plan-tab" id="new-plan">+ Criar plano</button>'}</div><section class="program-intro"><div class="program-intro-head"><div><span class="eyebrow">${esc(p.kind||'Plano pessoal')} · ${esc(p.duration||'Tempo livre')}</span><h2>${esc(p.name)}</h2></div><span class="count-chip">${p.exercises.length} exercícios · ${total} séries</span><button class="btn" id="start-session">Começar sessão ↓</button></div>${p.description?`<p>${esc(p.description)}</p>`:''}${isCurrentCourse(p)&&p.course.session!=='M'?sourceComparison(p):''}${p.warmup?`<p class="visible-warmup"><b>Aquecimento / início:</b> ${esc(p.warmup)}</p>`:''}${p.primary&&p.kind==='Hipertrofia'?'<div class="program-rule"><b>Um ciclo simples:</b> repete a sessão nos três dias. Começa com as variantes de casa já preparadas, regista a mesma unidade de carga e termina cada série com 2–3 boas repetições ainda possíveis. Procura progredir em repetições antes de aumentar o peso.</div>':''}<details><summary>Como seguir, progressão e origem da ficha</summary><p>${esc(p.note)}</p>${p.warmup?`<p><b>Aquecimento:</b> ${esc(p.warmup)}</p>`:''}${p.progression?`<p><b>Progressão:</b> ${esc(p.progression)}</p>`:''}${p.provenance?`<p><b>Vídeo / adaptações:</b> ${esc(p.provenance)}</p>`:''}${p.video?`<button class="mini" id="program-video">▶ Ver o vídeo de base</button>`:''}${p.sourceExact?'<p class="small-source">Séries e objetivos preservados do excerto fornecido. Descansos e frequência não foram especificados nesse excerto.</p>':'<p class="small-source">O volume e a margem de esforço desta ficha são adaptações; <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM 2026</a>. Não é uma reprodução do programa privado da Skool.</p>'}</details>${previous?`<p class="last-session">Última sessão guardada: ${dateLabel(previous.date)} · ${previous.exercises.reduce((n,e)=>n+e.rows.length,0)} séries concluídas.</p>`:''}</section><div class="guide-toolbar"><span>${d.guided?'Modo guiado · segue a ordem':'Visão completa · todos os exercícios'}</span><button class="btn secondary" id="toggle-guide">${d.guided?'Ver todos os exercícios':'Seguir passo a passo'}</button></div><div class="plan-layout"><section class="panel"><div class="plan-header"><label class="sr-only" for="plan-name">Nome do treino</label><input class="plan-name" id="plan-name" aria-label="Nome do treino" maxlength="100" value="${esc(p.name)}"><span class="draft-badge">● Guardado ao preencher</span></div><details class="plan-custom"><summary>Notas e ajustes pessoais</summary><textarea class="plan-notes" id="plan-notes" aria-label="Notas e orientações do plano" maxlength="2000">${esc(p.note)}</textarea><button class="mini" id="duplicate-plan">Duplicar este treino</button><button class="mini" id="export-plan">Exportar só este plano</button></details>${d.guided&&current?`<div class="step-label">Passo ${d.step+1} de ${steps.length}${current.label?' · '+esc(current.label):''}</div>`:''}<div id="exercises">${p.exercises.length?(d.guided&&current?exerciseHTML(p.exercises[current.index],current.index,d,current.row):p.exercises.map((e,i)=>exerciseHTML(e,i,d)).join('')):'<div class="empty"><h3>Adiciona o primeiro exercício.</h3>Também podes escolher uma rotina já preparada.</div>'}</div>${d.guided&&current?`<div class="guide-controls"><button class="btn secondary" id="step-prev" ${d.step===0?'disabled':''}>← Anterior</button><span>${d.step+1} / ${steps.length}</span><button class="btn" id="step-next" ${d.step===steps.length-1?'disabled':''}>Seguinte →</button></div>`:''}<button class="btn secondary full" id="add-exercise" style="margin-top:15px">${icon('plus')} Adicionar exercício</button><div class="session-meta"><label>Data do treino<input type="date" id="session-date" value="${esc(d.date)}" required></label><label>Notas da sessão<input id="session-note" placeholder="Esforço, variantes, desconforto…" maxlength="2000" value="${esc(d.note)}"></label></div>${isCurrentCourse(p)?`<div class="session-extra"><label>Margem real no fim das séries<select id="session-effort"><option value="">Não registei</option><option value="4+">4 ou mais repetições</option><option value="3–4">3–4 repetições</option><option value="2–3">2–3 repetições</option><option value="0–1">0–1 repetições</option></select></label><label>Duração real · minutos<input id="session-duration" type="number" min="1" max="240" placeholder="Opcional" value="${esc(d.duration||'')}"></label></div><p class="course-dosage-note">Se já atingiste o teu tempo, guarda o que fizeste. A sessão pode ficar parcial; não é preciso apressar a execução para a marcar completa.</p>`:''}<button class="btn full" id="finish">${d.editHistoryId?'Guardar alterações ao registo':'Guardar sessão no histórico'} <span aria-hidden="true">↗</span></button>${d.editHistoryId?'<button class="btn secondary full" id="cancel-edit" style="margin-top:8px">Cancelar edição; manter o registo anterior</button>':''}<p class="privacy">Regista o que fizeste e marca ✓. Os objetivos estão na ficha; só as séries assinaladas entram no histórico.</p></section><aside><div class="timer-panel"><span class="eyebrow">Tempo de descanso</span><div id="timer" class="timer" role="timer" aria-label="Tempo restante">01:30</div><div class="timer-choices">${[60,90,120].map(n=>`<button data-rest="${n}" class="${restDuration===n?'active':''}">${n}s</button>`).join('')}</div><div class="timer-bottom"><button class="btn lime" id="timer-toggle">Iniciar</button><button class="btn secondary" id="timer-reset" aria-label="Reiniciar temporizador">↺</button></div></div><div class="side-summary"><h3>Nesta sessão</h3><div id="session-progress"></div><ol class="exercise-order">${p.exercises.map((e,i)=>`<li><button data-go-ex="${i}" class="${d.guided&&current?.index===i?'current':''}">${esc(e.name)}</button></li>`).join('')}</ol><p>Se o desconforto aumentar ou a técnica se perder, ajusta ou interrompe o movimento. Mantém as adaptações que tens tolerado.</p></div></aside></div>`;
 document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{selectedPlan=b.dataset.plan;renderPlans()});$('#start-session').onclick=()=>$('#exercises').scrollIntoView({behavior:'smooth',block:'start'});$('#other-plans').onclick=otherPlans;if($('#new-plan'))$('#new-plan').onclick=newPlanForm;if($('#course-home'))$('#course-home').onclick=()=>{selectedPlan='';if(state.courseEnabled===false)renderHome();else chooseCourse(state.courseWeek||1,state.courseSession||'A')};if(isCurrentCourse(p))bindCourse(p);$('#toggle-guide').onclick=()=>{d.guided=!d.guided;persist();renderPlans()};$('#plan-name').onchange=e=>{p.name=e.target.value.trim()||p.name;persist();renderPlans()};$('#plan-notes').oninput=e=>{p.note=e.target.value;persist()};$('#session-date').onchange=e=>{if(e.target.value){d.date=e.target.value;d.datePinned=true;persist();renderPlans()}};$('#session-note').oninput=e=>{d.note=e.target.value;persist()};$('#add-exercise').onclick=()=>exerciseForm();$('#finish').onclick=finishSession;if($('#cancel-edit'))$('#cancel-edit').onclick=()=>{delete state.drafts[p.id];persist();setView('history')};if($('#session-effort')){$('#session-effort').value=d.effort||'';$('#session-effort').onchange=e=>{d.effort=e.target.value;persist()};$('#session-duration').oninput=e=>{if(e.target.checkValidity()){d.duration=e.target.value;persist()}};}$('#export-plan').onclick=exportCurrentPlan;$('#duplicate-plan').onclick=()=>{if(state.plans.length>=256)return toast('Limite de 256 treinos atingido.');const copy=JSON.parse(JSON.stringify(p));copy.id=uid();copy.primary=false;copy.prepared=false;delete copy.course;copy.name=(p.name+' · cópia').slice(0,100);copy.exercises.forEach(e=>e.id=uid());state.plans.push(copy);selectedPlan=copy.id;persist();renderPlans();toast('Treino duplicado.')};if($('#program-video'))$('#program-video').onclick=()=>openVideo(p.video);
 if($('#step-prev'))$('#step-prev').onclick=()=>{d.step--;persist();renderPlans()};if($('#step-next'))$('#step-next').onclick=()=>{d.step++;persist();renderPlans()};document.querySelectorAll('[data-go-ex]').forEach(b=>b.onclick=()=>{d.guided=true;d.step=steps.findIndex(s=>s.index===+b.dataset.goEx);persist();renderPlans()});
 bindExercises();document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>changeVariant(p.exercises.find(e=>e.id===b.dataset.variant)));document.querySelectorAll('[data-copy-last]').forEach(b=>b.onclick=()=>{const e=p.exercises.find(e=>e.id===b.dataset.copyLast),last=previousExercise(e,d.date);if(!last)return;d.rows[e.id].forEach((r,i)=>{if(!r.kg)r.kg=last.rows[Math.min(i,last.rows.length-1)].kg});persist();renderPlans();toast('Cargas anteriores copiadas; regista as repetições desta sessão.')});bindTimer();document.querySelectorAll('[data-use-rest]').forEach(b=>b.onclick=()=>{restDuration=+b.dataset.useRest;restRemaining=restDuration;restRunning=false;updateTimer();$('#timer').scrollIntoView({block:'nearest',behavior:'smooth'})});updateProgress();
}
function exerciseHTML(e,i,d,onlyRow=null){const rows=d.rows[e.id]||[],last=previousExercise(e,d.date);return `<article class="exercise" data-exercise="${esc(e.id)}"><div class="exercise-top"><div class="exercise-title"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><small>${rows.length} séries · ${esc(targetLabel(e))}${onlyRow!==null?' · agora: série '+(onlyRow+1):''}</small>${e.adapted?'<span class="adapted-tag">Variante alternativa preparada</span>':''}${e.video?`<button class="mini" data-ref="${esc(e.id)}">▶ Ver demonstração${e.start?' · '+Math.floor(e.start/60)+':'+String(e.start%60).padStart(2,'0'):''}</button>`:''}</div></div><div class="exercise-tools"><button class="mini" data-edit="${esc(e.id)}">Editar</button><button class="mini" data-remove="${esc(e.id)}" aria-label="Retirar ${esc(e.name)}">Retirar</button></div></div>${e.block?`<p class="block-note">${esc(e.block)}</p>`:''}${e.how?`<p class="how">${esc(e.how)}</p>`:''}${e.cue?`<p class="cue-note">${esc(e.cue)}</p>`:''}<div class="dose-strip"><span><b>Objetivo</b>${esc(targetLabel(e))}</span><span><b>Descanso</b>${Number.isFinite(e.restSeconds)?(e.restSeconds===0?'Passar ao seguinte':e.restSeconds+' s'):'Ajustável'}</span>${e.restSeconds>0?`<button class="mini" data-use-rest="${Math.min(3600,e.restSeconds)}">Usar no temporizador</button>`:''}</div>${e.note?`<p class="load-note">${esc(e.note)}</p>`:''}${e.loadHint&&!last?`<p class="load-hint">${esc(e.loadHint)}</p>`:''}${e.alternative?`<button class="variant-button" data-variant="${esc(e.id)}">↔ ${esc(e.alternative.label||'Usar alternativa preparada')}</button>`:''}${e.originalDose?`<p class="original-dose"><b>Dose original do vídeo:</b> ${esc(e.originalDose)}</p>`:''}${e.sourceDose?`<details class="source-detail"><summary>O que vem do vídeo / adaptações</summary><p>${esc(e.sourceDose)}</p></details>`:''}${last?`<div class="previous-load"><b>Último registo · ${dateLabel(last.date)}</b><span>${last.rows.map(r=>`${r.kg!==''?esc(r.kg)+' kg × ':''}${esc(r.reps)} ${unitLabel(e)}`).join(' · ')}</span><button class="mini" data-copy-last="${esc(e.id)}">Copiar cargas anteriores</button></div>`:''}<div class="set-grid head"><span>Série</span><span>Carga · kg</span><span>${e.unit==='s'?'Tempo · s':e.unit==='steps'?'Passos':'Repetições'}</span><span>Feita</span></div>${rows.map((r,j)=>onlyRow!==null&&onlyRow!==j?'':`<div class="set-grid set-row"><span class="set-index">${j+1}</span>${e.noLoad?'<span class="no-load">Sem carga</span>':`<input type="number" min="0" max="100000" step="0.25" inputmode="decimal" placeholder="—" value="${esc(r.kg)}" aria-label="Carga, ${esc(e.name)}, série ${j+1}" data-field="kg" data-e="${esc(e.id)}" data-row="${j}">`}<input type="number" min="0" max="100000" step="1" inputmode="numeric" placeholder="${esc((e.target||'').match(/^\d+/)?.[0]||'—')}" value="${esc(r.reps)}" aria-label="${e.unit==='s'?'Segundos':e.unit==='steps'?'Passos':'Repetições'}, ${esc(e.name)}, série ${j+1}" data-field="reps" data-e="${esc(e.id)}" data-row="${j}"><button class="tick ${r.done?'done':''}" data-tick="${esc(e.id)}" data-row="${j}" aria-label="Concluir série ${j+1} de ${esc(e.name)}" aria-pressed="${r.done}">✓</button></div>`).join('')}${onlyRow===null?`<button class="add-set" data-add-set="${esc(e.id)}">+ Adicionar série</button>`:''}</article>`}

function bindExercises(){const p=getPlan(),d=getDraft(p);
 document.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const value=input.value;if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>100000)){input.setCustomValidity('Indica um valor entre 0 e 100000.');return;}input.setCustomValidity('');const r=d.rows[input.dataset.e][+input.dataset.row];r[input.dataset.field]=value;if(input.dataset.field==='reps'&&Number(value)<=0){r.done=false;const b=input.parentElement.querySelector('.tick');b.classList.remove('done');b.setAttribute('aria-pressed','false')}persist();updateProgress()});
 document.querySelectorAll('[data-tick]').forEach(b=>b.onclick=()=>{const r=d.rows[b.dataset.tick][+b.dataset.row];if(!r.done&&(!r.reps||+r.reps<=0)){toast('Preenche as repetições, os segundos ou os passos antes de concluir a série.');return}r.done=!r.done;persist();b.classList.toggle('done',r.done);b.setAttribute('aria-pressed',String(r.done));updateProgress()});
 document.querySelectorAll('[data-add-set]').forEach(b=>b.onclick=()=>{const e=p.exercises.find(e=>e.id===b.dataset.addSet);if(d.rows[e.id].length>=30)return toast('Máximo de 30 séries por exercício.');d.rows[e.id].push(blankRow());e.sets=d.rows[e.id].length;persist();renderPlans()});
 document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>{const e=p.exercises.find(e=>e.id===b.dataset.ref);openVideo(e.video,e.start)});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>exerciseForm(p.exercises.find(e=>e.id===b.dataset.edit)));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const e=p.exercises.find(e=>e.id===b.dataset.remove);modal('Retirar exercício',`<p>Retirar “${esc(e.name)}” deste plano e do rascunho atual? As sessões já guardadas mantêm-se no histórico.</p><div class="form-actions"><button class="btn secondary" id="cancel-remove">Cancelar</button><button class="btn danger" id="confirm-remove">Retirar exercício</button></div>`,true);$('#cancel-remove').onclick=closeModal;$('#confirm-remove').onclick=()=>{p.exercises=p.exercises.filter(x=>x.id!==e.id);delete d.rows[e.id];persist();closeModal();renderPlans();toast('Exercício retirado do plano.')};});
}
function updateProgress(){const p=getPlan(),d=getDraft(p);const rows=p.exercises.flatMap(e=>d.rows[e.id]||[]);const done=rows.filter(r=>r.done).length;if($('#session-progress'))$('#session-progress').innerHTML=`<span>${done} de ${rows.length} séries concluídas</span><div class="progress"><span style="width:${rows.length?done/rows.length*100:0}%"></span></div><span>${p.exercises.length} exercícios no plano</span>`;}
function parseVideo(s){if(!s.trim())return '';if(/^[\w-]{11}$/.test(s.trim()))return s.trim();try{const u=new URL(s);if(!['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtube-nocookie.com'].includes(u.hostname))return null;const id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.match(/\/(?:shorts|embed)\/([\w-]{11})/)?.[1];return /^[\w-]{11}$/.test(id||'')?id:null;}catch{return null}}
function exerciseForm(existing=null,video=''){const p=getPlan();if(!existing&&p.exercises.length>=100)return toast('Limite de 100 exercícios por treino.');const e=existing||ex('',video);modal(existing?'Editar exercício':'Adicionar exercício',`<form id="exercise-form"><div class="form-grid"><label class="wide">Nome do exercício<input id="e-name" required maxlength="200" placeholder="Ex.: Flexão inclinada" value="${esc(e.name)}"></label><label class="wide">Vídeo YouTube <small>· opcional</small><input id="e-video" placeholder="URL ou ID do vídeo" value="${e.video?'https://www.youtube.com/watch?v='+esc(e.video):''}"></label><label>Linhas / séries de registo<input id="e-sets" type="number" min="1" max="30" step="1" required value="${e.sets}"></label><label>Medida<select id="e-unit"><option value="reps">Repetições</option><option value="s">Segundos</option><option value="steps">Passos</option></select></label><label>Objetivo <small>· opcional</small><input id="e-target" maxlength="60" placeholder="Ex.: 8–12" value="${esc(e.target)}"></label><label>Início do vídeo · segundos<input id="e-start" type="number" min="0" max="86400" step="1" value="${e.start}" required></label><label class="wide">Notas do exercício<textarea id="e-note" maxlength="2000" placeholder="Progressão, técnica, material…">${esc(e.note)}</textarea></label></div><p class="dialog-note">As séries são a estrutura do teu registo. Preenche os objetivos a partir do vídeo ou do teu plano.</p><div class="form-actions"><button class="btn secondary" type="button" id="e-cancel">Cancelar</button><button class="btn" type="submit">Guardar exercício</button></div></form>`,true);$('#e-unit').value=e.unit;$('#e-cancel').onclick=closeModal;$('#exercise-form').onsubmit=ev=>{ev.preventDefault();const name=$('#e-name').value.trim();if(!name)return toast('Indica o nome do exercício.');const videoId=parseVideo($('#e-video').value);if(videoId===null)return toast('Indica um URL válido do YouTube.');const count=Number($('#e-sets').value);const d=getDraft(p);const old=d.rows[e.id]||[];if(old.slice(count).some(r=>r.done||r.kg||r.reps))return toast('As séries finais têm registos. Mantém esse número de séries até guardares a sessão.');Object.assign(e,{name,video:videoId,sets:count,unit:$('#e-unit').value,target:$('#e-target').value.trim(),start:Number($('#e-start').value),note:$('#e-note').value.trim()});if(!existing)p.exercises.push(e);d.rows[e.id]=Array.from({length:count},(_,i)=>old[i]||blankRow());persist();closeModal();renderPlans();toast('Exercício guardado.')};}
function newPlanForm(){if(state.plans.length>=256)return toast('Limite de 256 treinos atingido.');modal('Criar treino',`<form id="new-plan-form"><label>Nome do treino<input id="new-name" required maxlength="100" placeholder="Ex.: Treino de segunda-feira"></label><div class="form-actions"><button type="button" class="btn secondary" id="new-cancel">Cancelar</button><button class="btn" type="submit">Criar treino</button></div></form>`,true);$('#new-cancel').onclick=closeModal;$('#new-plan-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim();if(!name)return;const p={id:uid(),name,note:'',exercises:[]};state.plans.push(p);selectedPlan=p.id;persist();closeModal();renderPlans()};}
function finishSession(){
 const p=getPlan(),d=getDraft(p);if(!$('#session-date').checkValidity()){$('#session-date').reportValidity();return}
 if($('#session-duration')&&!$('#session-duration').checkValidity()){$('#session-duration').reportValidity();return}
 const exercises=p.exercises.map(e=>({id:e.id,name:e.name,unit:e.unit,loadUnit:e.note||'',rows:(d.rows[e.id]||[]).map((r,setIndex)=>({...r,setIndex})).filter(r=>r.done)})).filter(e=>e.rows.length);
 if(!exercises.length)return toast('Conclui pelo menos uma série para guardar a sessão.');
 const done=exercises.reduce((n,e)=>n+e.rows.length,0),total=p.exercises.reduce((n,e)=>n+(d.rows[e.id]||[]).length,0),complete=done>=total;
 const oldIndex=d.editHistoryId?state.history.findIndex(h=>h.id===d.editHistoryId):-1;const record={id:oldIndex>=0?state.history[oldIndex].id:uid(),planId:p.id,planName:p.name,date:d.date,note:d.note,savedAt:oldIndex>=0?state.history[oldIndex].savedAt:Date.now(),exercises,complete,course:p.course?{...p.course,week:courseWeek(p)}:null,effort:d.effort||'',duration:d.duration||''};if(oldIndex>=0)state.history[oldIndex]=record;else state.history.unshift(record);
 delete state.drafts[p.id];persist();toast(storageOK?(complete?'Sessão completa guardada.':'Sessão parcial guardada; os registos ficam no histórico.'):'Sessão registada em memória. Exporta uma cópia antes de fechar.');setView('history');
}
function reopenSession(id){
 const h=state.history.find(x=>x.id===id);if(!h)return;
 const p=state.plans.find(x=>x.id===h.planId)||state.plans.find(x=>x.name===h.planName);if(!p)return toast('O plano de origem não está disponível; o registo continua preservado.');
 if(h.exercises.some(saved=>!p.exercises.some(e=>e.id===saved.id&&e.name===saved.name&&e.unit===saved.unit)))return toast('As variantes do plano foram alteradas. O registo original mantém-se no histórico; consulta-o antes de editar.');
 const existing=state.drafts[p.id];if(existing&&existing.editHistoryId!==h.id&&(existing.note||Object.values(existing.rows).some(rows=>rows.some(r=>r.kg||r.reps||r.done))))return toast('Há um rascunho preenchido neste plano. Guarda-o antes de reabrir outro registo.');
 const d={date:h.date,datePinned:true,note:h.note,rows:{},guided:false,step:0,editHistoryId:h.id,effort:h.effort||'',duration:h.duration||''};
 for(const e of p.exercises){const saved=h.exercises.find(x=>x.id===e.id);const max=saved?Math.max(e.sets,...saved.rows.map((r,i)=>(Number.isInteger(r.setIndex)?r.setIndex:i)+1)):e.sets;d.rows[e.id]=Array.from({length:Math.min(30,max)},blankRow);if(saved)saved.rows.forEach((r,i)=>{const j=Number.isInteger(r.setIndex)?r.setIndex:i;if(j<30)d.rows[e.id][j]={kg:r.kg,reps:r.reps,done:r.done};});}
 state.drafts[p.id]=d;selectedPlan=p.id;if(isCurrentCourse(p)){state.courseWeek=h.course?.week||p.course.week;state.courseSession=p.course.session;}persist();setView('plans');toast('Registo reaberto. Guardar substitui esta sessão; não cria uma cópia.');
}

function dateLabel(s){return new Date(s+'T12:00:00').toLocaleDateString('pt-PT',{day:'numeric',month:'short',year:'numeric'})}
function renderHistory(){const history=[...state.history].sort((a,b)=>b.date.localeCompare(a.date)||b.savedAt-a.savedAt);const count=history.reduce((s,h)=>s+h.exercises.reduce((n,e)=>n+e.rows.length,0),0);const volume=history.reduce((sum,h)=>sum+(Number(h.duration)||0),0);
 $('#content').innerHTML=heading('Cada sessão conta.','O teu histórico, construído série a série. Podes voltar a qualquer registo.')+`<div class="stats"><div class="stat"><strong>${history.length}</strong><span>Sessões guardadas</span></div><div class="stat"><strong>${count}</strong><span>Séries concluídas</span></div><div class="stat"><strong>${new Intl.NumberFormat('pt-PT',{maximumFractionDigits:1}).format(volume)}</strong><span>Minutos registados</span></div></div><div class="history-list">${history.length?history.map(h=>`<details class="history-item"><summary><div><h3>${esc(h.planName)}</h3><span class="summary-date">${dateLabel(h.date)} · ${h.exercises.length} ${h.exercises.length===1?'exercício':'exercícios'} · ${h.exercises.reduce((n,e)=>n+e.rows.length,0)} ${h.exercises.reduce((n,e)=>n+e.rows.length,0)===1?'série':'séries'}</span></div><span aria-hidden="true">⌄</span></summary><div class="history-body">${h.course?`<span class="history-tag">${h.complete?'Completa':'Parcial'} · semana ${esc(h.course.week)}</span>`:''}${h.duration?`<p>Duração: ${esc(h.duration)} min${h.effort?' · margem: '+esc(h.effort)+' reps':''}</p>`:h.effort?`<p>Margem registada: ${esc(h.effort)} reps</p>`:''}${h.note?`<p>${esc(h.note)}</p>`:''}${h.exercises.map(e=>`<div class="history-ex"><strong>${esc(e.name)}</strong>${e.loadUnit?`<small>${esc(e.loadUnit)}</small>`:''}<span>${e.rows.map((r,i)=>`${i+1}: ${esc(r.reps)} ${unitLabel(e)}${r.kg!==''?' × '+esc(r.kg)+' kg':''}`).join(' · ')}</span></div>`).join('')}<button class="btn secondary recovery-button" data-reopen="${esc(h.id)}">${h.complete===false?'Retomar sessão parcial':'Reabrir / corrigir registo'}</button></div></details>`).join(''):`<div class="empty"><h3>A tua primeira sessão fica aqui.</h3>Abre um treino, preenche os registos e marca as séries feitas.<br><button class="btn" id="history-start">Ir para os meus treinos ↗</button></div>`}</div><p class="privacy">Compara cargas no mesmo exercício, na mesma variante e unidade. Kg por haltere, kg totais da barra, passos e segundos são registos diferentes.</p>`;if($('#history-start'))$('#history-start').onclick=()=>setView('plans');document.querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>reopenSession(b.dataset.reopen));
}
function formatTime(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function updateTimer(){if(restRunning){restRemaining=Math.max(0,Math.ceil((restUntil-Date.now())/1000));if(!restRemaining){restRunning=false;toast('Descanso terminado.')}}if($('#timer'))$('#timer').textContent=formatTime(restRemaining);if($('#timer-toggle'))$('#timer-toggle').textContent=restRunning?'Pausar':restRemaining===0?'Recomeçar':'Iniciar';}
function bindTimer(){document.querySelectorAll('[data-rest]').forEach(b=>b.onclick=()=>{restDuration=+b.dataset.rest;restRemaining=restDuration;restRunning=false;document.querySelectorAll('[data-rest]').forEach(x=>x.classList.toggle('active',x===b));updateTimer()});$('#timer-toggle').onclick=()=>{if(restRunning){restRemaining=Math.max(0,Math.ceil((restUntil-Date.now())/1000));restRunning=false;}else{if(restRemaining===0)restRemaining=restDuration;restUntil=Date.now()+restRemaining*1000;restRunning=true}updateTimer()};$('#timer-reset').onclick=()=>{restRunning=false;restRemaining=restDuration;updateTimer()};updateTimer()}
setInterval(updateTimer,500);
function downloadBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`treinos-bioforceman-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);toast('Cópia de segurança exportada. Guarda o ficheiro JSON.');}
$('#export').innerHTML=icon('download')+' Exportar cópia';$('#export').onclick=downloadBackup;$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;if(file.size>15*1024*1024)return toast('O ficheiro é demasiado grande (máximo 15 MB).');let incoming;try{incoming=JSON.parse(await file.text());if(incoming?.format==='treino-plan'){importSinglePlan(incoming.plan);return;}if(!validState(incoming))throw Error('invalid')}catch{return toast('O ficheiro não é uma cópia de segurança válida desta página.');}modal('Importar cópia de segurança',`<p>Esta cópia contém <strong>${incoming.plans.length} ${incoming.plans.length===1?'treino':'treinos'}</strong> e <strong>${incoming.history.length} ${incoming.history.length===1?'sessão':'sessões'}</strong>. A importação substitui os dados atuais deste navegador.</p><p class="dialog-note">Exporta os registos atuais antes de os substituíres.</p><div class="form-actions"><button class="btn secondary" id="before-import">Exportar atuais</button><button class="btn" id="confirm-import">Substituir pelos dados da cópia</button></div>`,true);$('#before-import').onclick=downloadBackup;$('#confirm-import').onclick=()=>{state=incoming;installPrepared();selectedPlan=state.plans[0].id;state.courseEnabled??=true;storageOK=true;if(persist()){$('#storage-error').hidden=true;toast('Cópia importada e guardada.')}else toast('Cópia importada em memória. Não foi possível guardar no navegador.');closeModal();render()};};
const navNames={library:'Vídeos e fontes',plans:'Os meus treinos',history:'Histórico'};document.querySelectorAll('[data-view]').forEach(b=>{b.innerHTML=icon(b.dataset.view)+navNames[b.dataset.view];b.onclick=()=>{if(b.dataset.view==='plans')selectedPlan='';setView(b.dataset.view)}});
function startApp(){installPrepared();state.courseEnabled??=true;selectedPlan=state.courseEnabled===false?'':state.plans.some(p=>p.id===courseId(state.courseWeek||1,state.courseSession||'A'))?courseId(state.courseWeek||1,state.courseSession||'A'):state.plans[0].id;render();if(storageOK)persist();}

function exportCurrentPlan(){
 const p=JSON.parse(JSON.stringify(getPlan()));delete p.course;delete p.primary;delete p.prepared;delete p.sourceExact;
 const blob=new Blob([JSON.stringify({format:'treino-plan',version:1,plan:p},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='plano-treino-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);toast('Plano exportado sem histórico, cargas realizadas ou rascunhos.');
}
function importSinglePlan(plan){
 if(!validState({version:1,plans:[plan],drafts:{},history:[],favorites:[]}))throw Error('invalid plan');
 if(state.plans.length>=256)return toast('Limite de planos atingido.');
 modal('Adicionar uma ficha de treino',`<p>Adicionar “${esc(plan.name)}” com ${plan.exercises.length} exercícios? Os teus planos e registos atuais mantêm-se.</p><button class="btn" id="import-single-plan">Adicionar plano</button>`);
 $('#import-single-plan').onclick=()=>{const p=JSON.parse(JSON.stringify(plan));p.id=uid();delete p.course;p.prepared=false;p.primary=false;p.sourceExact=false;p.exercises.forEach(e=>e.id=uid());state.plans.push(p);selectedPlan=p.id;persist();closeModal();setView('plans');toast('Plano adicionado. Os registos anteriores mantêm-se.');};
}
